// ApplyKit.js
// One screen per application: your details → tailored résumé lines (accept
// each) → answers to the real form → open the application and submit it
// yourself → a receipt of exactly what went out. Nothing is auto-submitted.

import React, { useEffect, useMemo, useState } from "react";
import {
  ANSWER_FIELDS,
  loadAnswerBank,
  saveAnswerBank,
  planQuestions,
  tailorResume,
  draftAnswers,
  kitNeedsYou,
} from "./applyKitData";
import { fetchApplicationQuestions } from "./jobBoards";
import { getLastAIProvider } from "./jobHuntData";

function CopyBtn({ text }) {
  const [done, setDone] = useState(false);
  return (
    <button
      className="jh-link kit-copy"
      disabled={!text}
      onClick={async () => {
        try {
          await navigator.clipboard.writeText(text);
          setDone(true);
          setTimeout(() => setDone(false), 1400);
        } catch (e) {
          /* clipboard blocked: the text is selectable */
        }
      }}
    >
      {done ? "Copied" : "Copy"}
    </button>
  );
}

export default function ApplyKit({
  job,
  profile,
  onSave,
  onSubmitted,
  autoPrepare = false,
  applyStarted = false,
}) {
  const [bank, setBank] = useState(() => loadAnswerBank(profile));
  const [showBank, setShowBank] = useState(false);
  const [questions, setQuestions] = useState(null); // null = loading, [] = none published
  const [mode, setMode] = useState(job.kit?.tailoring?.mode || "honest");
  const [kit, setKit] = useState(job.kit || null);
  const [wantCover, setWantCover] = useState(!!job.kit?.coverLetter);
  const [busy, setBusy] = useState("");
  const [error, setError] = useState("");
  const [provider, setProvider] = useState("");

  const bankMissing = [
    "fullName",
    "email",
    "phone",
    "workAuth",
    "notice",
  ].filter((k) => !bank[k]?.trim());

  useEffect(() => {
    let alive = true;
    fetchApplicationQuestions(job).then((q) => alive && setQuestions(q || []));
    return () => {
      alive = false;
    };
  }, [job]);

  const realForm = questions && questions.length > 0;
  const plan = useMemo(
    () => (questions === null ? null : planQuestions(questions, bank, job)),
    [questions, bank, job]
  );

  // One-click Apply: start preparing as soon as we know the form.
  const [autoRan, setAutoRan] = useState(false);
  useEffect(() => {
    if (autoPrepare && !autoRan && !kit && plan) {
      setAutoRan(true);
      prepare();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [autoPrepare, plan]);

  const persist = (next) => {
    setKit(next);
    onSave(next);
  };

  const updateBank = (key, value) => {
    const next = { ...bank, [key]: value };
    setBank(next);
    saveAnswerBank(next);
  };

  const prepare = async () => {
    if (!plan || busy) return;
    setBusy("Tailoring your resume and drafting answers…");
    setError("");
    try {
      const [tailoring, drafted] = await Promise.all([
        tailorResume(profile, job, mode),
        plan.drafts.length || wantCover
          ? draftAnswers(profile, job, plan.drafts, bank, {
              coverLetter: wantCover,
            })
          : Promise.resolve({ answers: [], coverLetter: "" }),
      ]);
      setProvider(getLastAIProvider());
      persist({
        preparedAt: Date.now(),
        realForm,
        tailoring,
        accepted: tailoring.edits.map(() => true),
        direct: plan.direct,
        uploads: plan.uploads,
        answers: drafted.answers,
        coverLetter: drafted.coverLetter,
      });
    } catch (e) {
      setError(e.message || "Couldn't prepare the kit. Try again.");
    } finally {
      setBusy("");
    }
  };

  const retailor = async (nextMode) => {
    setMode(nextMode);
    if (!kit) return;
    setBusy(
      nextMode === "bold"
        ? "Rewriting in Bold mode…"
        : "Rewriting in Honest mode…"
    );
    setError("");
    try {
      const tailoring = await tailorResume(profile, job, nextMode);
      persist({ ...kit, tailoring, accepted: tailoring.edits.map(() => true) });
    } catch (e) {
      setError(e.message);
    } finally {
      setBusy("");
    }
  };

  const editAnswer = (list, idx, value) => {
    const items = [...kit[list]];
    items[idx] = {
      ...items[idx],
      answer: value,
      status: value.trim() ? "ready" : "needs_you",
    };
    persist({ ...kit, [list]: items });
  };

  const toggleEdit = (idx) => {
    const accepted = [...(kit.accepted || [])];
    accepted[idx] = !accepted[idx];
    persist({ ...kit, accepted });
  };

  const acceptedText = kit
    ? [
        kit.tailoring?.summary ? `Summary: ${kit.tailoring.summary}` : "",
        ...(kit.tailoring?.edits || [])
          .filter((_, i) => kit.accepted?.[i])
          .map((e) => `• ${e.rewritten}`),
      ]
        .filter(Boolean)
        .join("\n")
    : "";

  const needsYou = kitNeedsYou(kit);
  const applyUrl = job.applyUrl || job.url;

  const submit = () => {
    const receipt = {
      at: new Date().toISOString(),
      via: applyUrl,
      fields: [...(kit?.direct || []), ...(kit?.answers || [])].map((q) => ({
        label: q.label,
        answer: q.answer,
      })),
      resumeEdits: (kit?.tailoring?.edits || [])
        .filter((_, i) => kit.accepted?.[i])
        .map((e) => e.rewritten),
      coverLetter: kit?.coverLetter || "",
    };
    onSubmitted(receipt);
  };

  return (
    <div className="kit">
      {applyStarted && !job.receipt && (
        <div className="kit-live">
          <strong>The application form is open in a new tab.</strong>
          <span>
            Your answers are being prepared here. Copy each one across, upload
            your resume and submit. When you come back, we'll ask whether it
            went through.
          </span>
        </div>
      )}
      {job.receipt && (
        <div className="kit-receipt">
          <strong>
            Submitted {new Date(job.receipt.at).toLocaleDateString()}
          </strong>
          <span>
            {job.receipt.fields.length} answers and{" "}
            {job.receipt.resumeEdits.length} resume edits saved with this
            application.
          </span>
        </div>
      )}

      {/* 1 · Details */}
      <section className="kit-step">
        <header>
          <span className="kit-num">1</span>
          <div>
            <h4>Your details</h4>
            <p>
              {bankMissing.length
                ? `Saved once and reused on every application. Missing: ${bankMissing
                    .map((k) =>
                      ANSWER_FIELDS.find((f) => f.key === k).label.toLowerCase()
                    )
                    .join(", ")}.`
                : "Saved once, reused on every application. Stays in this browser."}
            </p>
          </div>
          <button className="jh-link" onClick={() => setShowBank((s) => !s)}>
            {showBank ? "Done" : "Edit"}
          </button>
        </header>
        {showBank && (
          <div className="kit-bank">
            {ANSWER_FIELDS.map((f) => (
              <label className="jh-field" key={f.key}>
                <span>{f.label}</span>
                <input
                  value={bank[f.key] || ""}
                  onChange={(e) => updateBank(f.key, e.target.value)}
                  placeholder={f.placeholder || ""}
                />
              </label>
            ))}
          </div>
        )}
      </section>

      {/* 2 · Prepare */}
      <section className="kit-step">
        <header>
          <span className="kit-num">2</span>
          <div>
            <h4>Prepare the kit</h4>
            <p>
              {questions === null
                ? "Checking the application form…"
                : realForm
                ? `Using the real application form from ${job.source} (${questions.length} fields).`
                : "This employer's form isn't published, so the kit covers the questions most forms ask."}
            </p>
          </div>
        </header>
        <div className="kit-controls">
          <div className="jh-seg" role="group" aria-label="Rewrite mode">
            <button
              className={mode === "honest" ? "on" : ""}
              onClick={() => (kit ? retailor("honest") : setMode("honest"))}
            >
              Honest
            </button>
            <button
              className={mode === "bold" ? "on" : ""}
              onClick={() => (kit ? retailor("bold") : setMode("bold"))}
            >
              Bold
            </button>
          </div>
          <label className="kit-check">
            <input
              type="checkbox"
              checked={wantCover}
              onChange={(e) => setWantCover(e.target.checked)}
            />
            Cover letter
          </label>
          <button
            className="jh-btn primary"
            onClick={prepare}
            disabled={!!busy || !plan}
          >
            {kit ? "Prepare again" : "Prepare kit"}
          </button>
        </div>
        <p className="jh-muted kit-modehint">
          {mode === "bold"
            ? "Bold leads with impact and the job's vocabulary. It still never adds experience you don't have."
            : "Honest keeps every claim as strong as your CV and only reframes it for this job."}
        </p>
        {busy && <div className="jh-draft-loading">{busy}</div>}
        {error && <div className="jh-error">{error}</div>}
      </section>

      {kit && (
        <>
          {/* 3 · Resume */}
          <section className="kit-step">
            <header>
              <span className="kit-num">3</span>
              <div>
                <h4>Resume for this role</h4>
                <p>
                  Untick anything you don't want. Copy the accepted lines into
                  your resume before uploading it.
                </p>
              </div>
              <CopyBtn text={acceptedText} />
            </header>
            {kit.tailoring?.summary && (
              <div className="kit-summary">
                <span className="jh-label">Summary line</span>
                <p>{kit.tailoring.summary}</p>
              </div>
            )}
            <ul className="kit-diff">
              {(kit.tailoring?.edits || []).map((e, i) => (
                <li key={i} className={kit.accepted?.[i] ? "" : "off"}>
                  <label>
                    <input
                      type="checkbox"
                      checked={!!kit.accepted?.[i]}
                      onChange={() => toggleEdit(i)}
                    />
                    <span className="kit-diff-body">
                      <del>{e.original}</del>
                      <ins>{e.rewritten}</ins>
                      {e.why && <em>{e.why}</em>}
                    </span>
                  </label>
                </li>
              ))}
            </ul>
          </section>

          {/* 4 · Answers */}
          <section className="kit-step">
            <header>
              <span className="kit-num">4</span>
              <div>
                <h4>Application answers</h4>
                <p>
                  {needsYou
                    ? `${needsYou} need${
                        needsYou === 1 ? "s" : ""
                      } you: things only you can confirm.`
                    : "Everything is drafted. Read each one before you paste it."}
                  {provider && (
                    <em className="jh-provider"> drafted via {provider}</em>
                  )}
                </p>
              </div>
            </header>
            {kit.uploads?.length > 0 && (
              <p className="kit-uploads">
                Upload on the form:{" "}
                {kit.uploads
                  .map((u) => u.label.replace(/\s+/g, " "))
                  .join(", ")}
              </p>
            )}
            <ol className="kit-answers">
              {["direct", "answers"].map((list) =>
                (kit[list] || []).map((q, idx) => (
                  <li
                    key={`${list}-${q.id}`}
                    className={q.status === "needs_you" ? "needs" : ""}
                  >
                    <div className="kit-q">
                      <span>
                        {q.label}
                        {q.required && <b className="kit-req">required</b>}
                      </span>
                      {q.status === "needs_you" ? (
                        <i className="kit-flag">Needs you</i>
                      ) : (
                        <CopyBtn text={q.answer} />
                      )}
                    </div>
                    {q.options?.length > 0 && q.status !== "needs_you" ? (
                      <select
                        className="jh-select"
                        value={q.answer}
                        onChange={(e) => editAnswer(list, idx, e.target.value)}
                      >
                        {!q.options.includes(q.answer) && (
                          <option value={q.answer}>
                            {q.answer || "Choose…"}
                          </option>
                        )}
                        {q.options.map((o) => (
                          <option key={o} value={o}>
                            {o}
                          </option>
                        ))}
                      </select>
                    ) : (
                      <textarea
                        rows={q.type === "textarea" ? 4 : 1}
                        value={q.answer}
                        onChange={(e) => editAnswer(list, idx, e.target.value)}
                        placeholder={
                          q.note ||
                          (q.options?.length
                            ? `One of: ${q.options.join(" / ")}`
                            : "Your answer")
                        }
                      />
                    )}
                    {q.note && q.status === "needs_you" && (
                      <span className="kit-note">{q.note}</span>
                    )}
                  </li>
                ))
              )}
            </ol>
            {kit.coverLetter && (
              <div className="kit-cover">
                <div className="kit-q">
                  <span>Cover letter</span>
                  <CopyBtn text={kit.coverLetter} />
                </div>
                <textarea
                  rows={9}
                  value={kit.coverLetter}
                  onChange={(e) =>
                    persist({ ...kit, coverLetter: e.target.value })
                  }
                />
              </div>
            )}
          </section>

          {/* 5 · Submit */}
          <section className="kit-step kit-submit">
            <header>
              <span className="kit-num">5</span>
              <div>
                <h4>Submit it yourself</h4>
                <p>
                  Open the form, paste each answer, upload your resume and press
                  Submit. Then record it here so the receipt is saved with the
                  application.
                </p>
              </div>
            </header>
            <div className="kit-controls">
              <a
                className="jh-btn"
                href={applyUrl}
                target="_blank"
                rel="noopener noreferrer"
              >
                Open application ↗
              </a>
              <button className="jh-btn primary" onClick={submit}>
                {job.receipt ? "Update receipt" : "I submitted it"}
              </button>
            </div>
          </section>
        </>
      )}
    </div>
  );
}
