import { onAuthStateChanged } from "firebase/auth";
import { auth } from "../../firebase/config";
import { useAuth } from "../../context/AuthContext";
import Header from "../../components/header/Header";
import {
  STATUSES,
  SEARCH_COUNTRIES,
  DEFAULT_PROFILE,
  EMPTY_PROFILE,
  setJobHuntScope,
  getJobHuntScope,
  parseCV,
  extractPdfText,
  scoreJobMatch,
  searchJobs,
  estimateMatch,
  loadApplications,
  saveApplications,
  loadProfile,
  saveProfile,
  fetchRemote,
  pushRemote,
  draftApplication,
  draftFollowUp,
  gmailComposeUrl,
  mailtoUrl,
  needsFollowUp,
  recruiterSearchLinks,
  getLastAIProvider,
  makeTrackId,
  registerTracking,
  fetchEngagement,
  suggestRecruiterEmails,
  sendViaGmail,
  applicationsToCsv,
  bandFor,
  DEFAULT_CV_URL,
} from "./jobHuntData";
import { EvalPanel } from "./JobHuntEvaluate";
import ApplyKit from "./ApplyKit";
import JobHuntHero from "./JobHuntHero";
import { kitNeedsYou } from "./applyKitData";
