const ATS_LABEL = { greenhouse: "Greenhouse", lever: "Lever", ashby: "Ashby" };

// Greenhouse returns HTML-escaped HTML; unescape once, then strip.
function decodeEntities(s) {
  if (!s) return "";
  try {
    const t = document.createElement("textarea");
    t.innerHTML = s;
    return t.value;
  } catch (e) {
    return s;
  }
}
const htmlToText = (html) => stripHtml(decodeEntities(html || ""));

function normGreenhouse(j, board) {
  return {
    id: `gh_${board.slug}_${j.id}`,
    title: j.title,
    company: board.name || j.company_name,
    location: j.location?.name || "",
    url: j.absolute_url,
    source: ATS_LABEL.greenhouse,
    ats: "greenhouse",
    board: board.slug,
    atsJobId: String(j.id),
    postedOn: (j.first_published || j.updated_at || "").slice(0, 10),
    jd: htmlToText(j.content).slice(0, 9000),
  };
}

function normLever(j, board) {
  const lists = (j.lists || [])
    .map((l) => `${l.text}: ${stripHtml(l.content)}`)
    .join("\n");
  return {
    id: `lv_${board.slug}_${j.id}`,
    title: j.text,
    company: board.name,
    location:
      j.categories?.location || j.categories?.allLocations?.join(", ") || "",
    url: j.hostedUrl,
    applyUrl: j.applyUrl,
    source: ATS_LABEL.lever,
    ats: "lever",
    board: board.slug,
    atsJobId: j.id,
    jobType: j.categories?.commitment || "",
    remote: j.workplaceType === "remote",
    postedOn: j.createdAt
      ? new Date(j.createdAt).toISOString().slice(0, 10)
      : "",
    jd: [j.descriptionPlain, lists, j.additionalPlain]
      .filter(Boolean)
      .join("\n")
      .slice(0, 9000),
  };
}

function normAshby(j, board) {
  return {
    id: `ab_${board.slug}_${j.id}`,
    title: j.title,
    company: board.name,
    location: [
      j.location,
      ...(j.secondaryLocations || []).map((l) => l.location),
    ]
      .filter(Boolean)
      .join(", "),
    url: j.jobUrl,
    applyUrl: j.applyUrl,
    source: ATS_LABEL.ashby,
    ats: "ashby",
    board: board.slug,
    atsJobId: j.id,
    jobType: j.employmentType || "",
    remote: !!j.isRemote || j.workplaceType === "Remote",
    postedOn: (j.publishedAt || "").slice(0, 10),
    jd: (j.descriptionPlain || htmlToText(j.descriptionHtml)).slice(0, 9000),
  };
}

// Boards are big (Databricks ~900 roles) and change slowly: cache per tab.
const CACHE_MS = 30 * 60 * 1000;
const cacheKey = (b) => `jobhunt.board.${b.ats}.${b.slug}`;

export async function fetchBoard(board) {
  try {
    const hit = JSON.parse(sessionStorage.getItem(cacheKey(board)) || "null");
    if (hit && Date.now() - hit.at < CACHE_MS) return hit.jobs;
  } catch (e) {
    /* ignore */
  }
  let jobs = [];
  if (board.ats === "greenhouse") {
    const r = await fetch(
      `https://boards-api.greenhouse.io/v1/boards/${board.slug}/jobs?content=true`
    );
    if (!r.ok) throw new Error(`${board.name}: ${r.status}`);
    jobs = ((await r.json()).jobs || []).map((j) => normGreenhouse(j, board));
  } else if (board.ats === "lever") {
    const r = await fetch(
      `https://api.lever.co/v0/postings/${board.slug}?mode=json`
    );
    if (!r.ok) throw new Error(`${board.name}: ${r.status}`);
    const d = await r.json();
    jobs = (Array.isArray(d) ? d : []).map((j) => normLever(j, board));
  } else if (board.ats === "ashby") {
    const r = await fetch(
      `https://api.ashbyhq.com/posting-api/job-board/${board.slug}`
    );
    if (!r.ok) throw new Error(`${board.name}: ${r.status}`);
    jobs = ((await r.json()).jobs || [])
      .filter((j) => j.isListed !== false)
      .map((j) => normAshby(j, board));
  }
  try {
    sessionStorage.setItem(
      cacheKey(board),
      JSON.stringify({ at: Date.now(), jobs })
    );
  } catch (e) {
    /* quota: fine, just refetch next time */
  }
  return jobs;
}

const STOP = new Set([
  "and",
  "the",
  "for",
  "with",
  "senior",
  "junior",
  "lead",
  "staff",
  "principal",
  "sr",
  "jr",
]);
export function titleTokens(q) {
  return (q || "")
    .toLowerCase()
    .split(/[^a-z0-9+#/]+/)
    .filter(
      (w) =>
        w &&
        (w.length > 2 || ["ai", "ml", "qa", "ux", "ui"].includes(w)) &&
        !STOP.has(w)
    );
}

// Indian cities go by two names on job boards; match either.
const CITY_ALIASES = [
  ["bengaluru", "bangalore"],
  ["gurugram", "gurgaon"],
  ["mumbai", "bombay"],
  ["chennai", "madras"],
  ["kolkata", "calcutta"],
  ["new delhi", "delhi", "ncr"],
  ["pune", "poona"],
];
function cityVariants(location) {
  const l = (location || "").trim().toLowerCase();
  if (!l) return [];
  return CITY_ALIASES.find((g) => g.some((c) => l.includes(c))) || [l];
}

// Fetch many boards in parallel; failures are reported, not fatal.
export async function fetchCompanyFeed({
  slugs,
  query = "",
  location = "",
  remoteOnly = false,
}) {
  const boards = COMPANY_BOARDS.filter((b) => slugs.includes(b.slug));
  const settled = await Promise.allSettled(boards.map(fetchBoard));
  const failed = [];
  let jobs = [];
  settled.forEach((s, i) => {
    if (s.status === "fulfilled") jobs = jobs.concat(s.value);
    else failed.push(boards[i].name);
  });
  const toks = titleTokens(query);
  const locs = cityVariants(location);
  jobs = jobs.filter((j) => {
    const t = (j.title || "").toLowerCase();
    if (
      toks.length &&
      !toks.some((w) =>
        w.length <= 2 ? new RegExp(`\\b${w}\\b`).test(t) : t.includes(w)
      )
    )
      return false;
    if (remoteOnly && !(j.remote || /remote/i.test(j.location))) return false;
    if (
      locs.length &&
      !locs.some((l) => (j.location || "").toLowerCase().includes(l)) &&
      !(remoteOnly && j.remote)
    )
      return false;
    return true;
  });
  return { jobs, failed, boards: boards.length };
}

// ===== Import a single job from its link =====
// Supports boards.greenhouse.io / job-boards.greenhouse.io / ?gh_jid=,
// jobs.lever.co and jobs.ashbyhq.com URLs.
export function parseJobLink(url) {
  let u;
  try {
    u = new URL(url.trim());
  } catch (e) {
    return null;
  }
  const host = u.hostname.replace(/^www\./, "");
  const parts = u.pathname.split("/").filter(Boolean);
  if (/greenhouse\.io$/.test(host) && parts.length >= 3 && parts[1] === "jobs")
    return { ats: "greenhouse", slug: parts[0], id: parts[2] };
  if (host === "jobs.lever.co" && parts.length >= 2)
    return { ats: "lever", slug: parts[0], id: parts[1] };
  if (host === "jobs.ashbyhq.com" && parts.length >= 2)
    return { ats: "ashby", slug: parts[0], id: parts[1] };
  const ghj = u.searchParams.get("gh_jid");
  if (ghj) {
    const known = COMPANY_BOARDS.find(
      (b) => b.ats === "greenhouse" && host.includes(b.slug)
    );
    if (known) return { ats: "greenhouse", slug: known.slug, id: ghj };
  }
  return null;
}

const titleCase = (s) =>
  s.replace(/(^|[-_ ])(\w)/g, (_, a, b) => (a ? " " : "") + b.toUpperCase());

export async function importJobFromLink(url) {
  const ref = parseJobLink(url);
  if (!ref)
    throw new Error(
      "That link isn't from Greenhouse, Lever or Ashby. Open the posting, copy its description, and use Evaluate a JD instead."
    );
  const board = COMPANY_BOARDS.find(
    (b) => b.ats === ref.ats && b.slug === ref.slug
  ) || {
    name: titleCase(ref.slug),
    ats: ref.ats,
    slug: ref.slug,
  };
  if (ref.ats === "greenhouse") {
    const r = await fetch(
      `https://boards-api.greenhouse.io/v1/boards/${ref.slug}/jobs/${ref.id}`
    );
    if (!r.ok)
      throw new Error(
        "Couldn't load that Greenhouse posting. It may have closed."
      );
    return normGreenhouse(await r.json(), board);
  }
  if (ref.ats === "lever") {
    const r = await fetch(
      `https://api.lever.co/v0/postings/${ref.slug}/${ref.id}?mode=json`
    );
    if (!r.ok)
      throw new Error("Couldn't load that Lever posting. It may have closed.");
    return normLever(await r.json(), board);
  }
  const jobs = await fetchBoard(board);
  const hit = jobs.find((j) => j.atsJobId === ref.id);
  if (!hit)
    throw new Error("Couldn't find that Ashby posting. It may have closed.");
  return hit;
}

// ===== The real application form (Greenhouse publishes it) =====
// Returns [{id, label, required, type, options:[...]}] with file uploads and
// the basic identity fields kept, so the kit can show what the form will ask.
export async function fetchApplicationQuestions(job) {
  if (job?.ats !== "greenhouse" || !job.board || !job.atsJobId) return null;
  try {
    const r = await fetch(
      `https://boards-api.greenhouse.io/v1/boards/${job.board}/jobs/${job.atsJobId}?questions=true`
    );
    if (!r.ok) return null;
    const d = await r.json();
    return (d.questions || []).map((q, i) => {
      const f = q.fields?.[0] || {};
      return {
        id: f.name || `q${i}`,
        label: (q.label || "").trim(),
        required: !!q.required,
        type: f.type || "input_text",
        options: (f.values || []).map((v) => v.label).filter(Boolean),
        description: htmlToText(q.description || "").slice(0, 300),
      };
    });
  } catch (e) {
    return null;
  }
}
