// applyKitData.js
// The "prepare everything, you press Submit" layer of the Job Copilot.
// (Named applyKitData, not applyKit: macOS filesystems are case-insensitive
// and ApplyKit.js is the component.)
//  - Answer bank: the facts every form asks (contact, work authorisation,
//    notice period, pay), saved once in this browser. The LLM never invents
//    them — anything missing comes back as "needs you".
//  - Résumé tailoring with a rewrite mode (Honest / Bold), shown as a diff
//    the user accepts line by line.
//  - Answers to the job's real application questions (Greenhouse publishes
//    them) or a standard set, each marked ready or "needs you".
//  - An optional cover letter.

import { getJobHuntScope, callAIJson, DEFAULT_PROFILE } from "./jobHuntData";

