const OWNER_DEFAULTS = {
  fullName: DEFAULT_PROFILE.fullName,
  linkedin: "https://linkedin.com/in/laxman-k-44913a156/",
  website: "https://laxman824.github.io/projects",
  phone: "+91-9000063740",
  location: "Bengaluru, India",
};

const bankKey = () =>
  getJobHuntScope() === "owner"
    ? "jobhunt.answers.v1"
    : "jobhunt.guest.answers.v1";

export function loadAnswerBank(profile) {
  let saved = {};
  try {
    saved = JSON.parse(localStorage.getItem(bankKey()) || "{}");
  } catch (e) {
    /* ignore */
  }
  const base = getJobHuntScope() === "owner" ? OWNER_DEFAULTS : {};
  return {
    ...base,
    fullName: profile?.fullName || base.fullName || "",
    ...saved,
  };
}

export function saveAnswerBank(bank) {
  try {
    localStorage.setItem(bankKey(), JSON.stringify(bank));
  } catch (e) {
    /* ignore */
  }
}

// Asked by almost every ATS when the job doesn't publish its own form.
export const STANDARD_QUESTIONS = [
  {
    id: "why_company",
    label: "Why do you want to work at {company}?",
    type: "textarea",
    required: true,
  },
  {
    id: "why_role",
    label: "Why are you a good fit for this role?",
    type: "textarea",
    required: true,
  },
  {
    id: "project",
    label: "Tell us about a project you're proud of.",
    type: "textarea",
  },
  {
    id: "start",
    label: "When can you start / what is your notice period?",
    type: "input_text",
  },
  {
    id: "sponsorship",
    label: "Will you require visa sponsorship?",
    type: "input_text",
  },
  {
    id: "salary",
    label: "What are your compensation expectations?",
    type: "input_text",
  },
];

// Identity fields are filled straight from the bank — no LLM involved.
const DIRECT = [
  [/^first name/i, (b) => (b.fullName || "").split(/\s+/)[0]],
  [/^last name/i, (b) => (b.fullName || "").split(/\s+/).slice(1).join(" ")],
  [/^(full )?name$/i, (b) => b.fullName],
  [/^email/i, (b) => b.email],
  [/^phone/i, (b) => b.phone],
  [/linkedin/i, (b) => b.linkedin],
  [/^(website|portfolio|github)/i, (b) => b.website],
  [/^(location|current location|city)/i, (b) => b.location],
];

export function directAnswer(label, bank) {
  const hit = DIRECT.find(([re]) => re.test((label || "").trim()));
  return hit ? hit[1](bank) || "" : null;
}

const isUpload = (q) =>
  q.type === "input_file" ||
  /resume\/cv|^resume|^cv$|cover letter$/i.test(q.label);

// Split the form into: filled from the bank, uploads, and questions to draft.
export function planQuestions(questions, bank, job) {
  const list = (questions && questions.length
    ? questions
    : STANDARD_QUESTIONS
  ).map((q) => ({
    ...q,
    label: q.label.replace("{company}", job.company || "the company"),
  }));
  const direct = [];
  const uploads = [];
  const drafts = [];
  list.forEach((q) => {
    if (isUpload(q)) return uploads.push(q);
    const v = directAnswer(q.label, bank);
    if (v !== null)
      return direct.push({
        ...q,
        answer: v,
        status: v ? "ready" : "needs_you",
      });
    drafts.push(q);
  });
  return { direct, uploads, drafts };
}

// ===== AI: résumé tailoring (diff) =====
export async function tailorResume(profile, job, mode = "honest") {
  const source = profile.cvText?.trim()
    ? profile.cvText.slice(0, 7000)
    : [profile.summary, ...(profile.keyProjects || [])]
        .filter(Boolean)
        .join("\n");
  const rules =
    mode === "bold"
      ? "BOLD mode: lead with impact, use the JD's vocabulary, reorder emphasis aggressively. Still never add employers, titles, numbers, tools or skills that are not in the source."
      : "HONEST mode: keep the claims exactly as strong as the source; rephrase only to surface what this JD cares about and use its terminology where it's genuinely the same thing.";
  const prompt = `You are an expert resume editor. Rewrite the candidate's most relevant resume lines for this specific job.

${rules}

RESUME SOURCE:
${source}

JOB: ${job.title} at ${job.company}
${(job.jd || "").slice(0, 5000)}

Pick the 4-7 lines/bullets from the source that matter most for this job and rewrite each. If a line has no honest improvement, skip it.
Also suggest a 1-2 sentence summary for the top of the resume, tailored to this job.

Return ONLY valid JSON:
{"summary": "string", "edits": [{"original": "exact or near-exact line from the source", "rewritten": "string", "why": "which JD requirement it now speaks to, under 90 chars"}]}`;
  const out = await callAIJson(prompt, 4096);
  if (!out?.edits) throw new Error("Couldn't tailor the resume. Try again.");
  return { summary: out.summary || "", edits: out.edits.slice(0, 8), mode };
}

// Questions the candidate must answer personally: legal attestations,
// compliance, consent, past employment with the company, demographics.
const ATTESTATION = /sanction|export control|certif|attest|acknowledg|consent|agree|privacy|policy|confirm whether|previously worked|currently work|worked for .* (before|in the past)|\breferr|\brelative|gender|pronoun|\brace\b|ethnic|hispanic|veteran|disab|criminal|convict|background check|non-compete|security clearance/i;

// ===== AI: answers + cover letter =====
export async function draftAnswers(
  profile,
  job,
  drafts,
  bank,
  { coverLetter = false } = {}
) {
  const facts = Object.fromEntries(
    ANSWER_FIELDS.map((f) => [f.label, bank[f.key] || "(not provided)"])
  );
  const prompt = `You are filling in a job application as the candidate, in FIRST PERSON. Be specific, warm and concise; no clichés ("passionate", "team player"), no flattery.

CANDIDATE PROFILE:
${JSON.stringify(
  {
    headline: profile.headline,
    yearsExperience: profile.yearsExperience,
    coreSkills: profile.coreSkills,
    summary: profile.summary,
    keyProjects: profile.keyProjects,
  },
  null,
  1
)}
${profile.cvText ? `\nCV EXCERPT:\n${profile.cvText.slice(0, 4000)}\n` : ""}
CANDIDATE FACTS (the ONLY source for logistics, authorisation, sponsorship, notice, pay, relocation):
${JSON.stringify(facts, null, 1)}

JOB: ${job.title} at ${job.company} (${job.location || "location not given"})
${(job.jd || "").slice(0, 4500)}

QUESTIONS (answer each by id):
${drafts
  .map(
    (q) =>
      `- id: ${q.id} | ${q.label}${q.required ? " (required)" : ""}${
        q.options?.length
          ? ` | choose exactly one of: ${q.options.join(" / ")}`
          : ""
      }`
  )
  .join("\n")}

RULES:
- Multiple choice: answer with one of the given options verbatim.
- Logistics/authorisation/sponsorship/pay/start date/relocation: use CANDIDATE FACTS only. If the fact is "(not provided)", set status "needs_you" and answer "".
- Policy acknowledgements or anything only the candidate can truthfully confirm (consent, AI-use policy, background checks, demographic/EEO questions): status "needs_you", answer "" and a short note.
- Open-ended: 60-140 words, tied to real projects and this JD. Never invent employers, numbers or experience.
${
  coverLetter
    ? '- Also write "coverLetter": 180-230 words, plain text, first person, mapped to the JD, signed with the candidate\'s name.'
    : ""
}

Return ONLY valid JSON:
{"answers": [{"id": "string", "answer": "string", "status": "ready|needs_you", "note": "string"}]${
    coverLetter ? ', "coverLetter": "string"' : ""
  }}`;
  const out = await callAIJson(prompt, 6144);
  if (!out?.answers) throw new Error("Couldn't draft the answers. Try again.");
  const byId = Object.fromEntries(out.answers.map((a) => [a.id, a]));
  return {
    answers: drafts.map((q) => {
      const a = byId[q.id] || {};
      const answer = (a.answer || "").trim();
      // Hard guard, not a prompt rule: attestations and personal history are
      // never pre-answered. The model's guess survives only as a hint.
      if (ATTESTATION.test(q.label)) {
        return {
          ...q,
          answer: "",
          status: "needs_you",
          note: `Only you can confirm this.${
            answer ? ` Likely answer: "${answer.slice(0, 80)}"` : ""
          }`,
        };
      }
      return {
        ...q,
        answer,
        note: a.note || "",
        status: a.status === "needs_you" || !answer ? "needs_you" : "ready",
      };
    }),
    coverLetter: out.coverLetter || "",
  };
}

// How many answers still need the human before submitting.
export function kitNeedsYou(kit) {
  if (!kit) return 0;
  return [...(kit.direct || []), ...(kit.answers || [])].filter(
    (q) => q.status === "needs_you"
  ).length;
}
