const escapeRe = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
function termRegex(term) {
  // Word-ish boundaries that respect tech punctuation (c++, node.js, ci/cd).
  // Optional plural so "vector databases" / "microservice" still match.
  return new RegExp(
    `(^|[^a-z0-9+#])${escapeRe(term.trim())}(?:s|es)?(?=$|[^a-z0-9+#])`,
    "g"
  );
}
function countTerm(term, hay) {
  const variants = [term, ...(KEYWORD_ALIASES[term] || [])];
  return variants.reduce(
    (n, v) => n + (hay.match(termRegex(v)) || []).length,
    0
  );
}

function profileHay(profile) {
  if (!profile) return "";
  return [
    profile.cvText || "",
    profile.headline,
    profile.summary,
    ...(profile.coreSkills || []),
    ...(profile.tools || []),
    ...(profile.domains || []),
    ...(profile.keyProjects || []),
    ...(profile.preferredTitles || []),
  ]
    .join(" \n ")
    .toLowerCase();
}

// Returns { score, hard:{found,missing}, soft:{found,missing}, titleMatch }.
// Keywords are ranked by how often the JD repeats them, with a boost for
// lines that read like requirements ("must", "required", "minimum").
export function scanKeywords(profile, jd, title = "") {
  const jdLower = ` ${(jd || "").toLowerCase()} `;
  const reqLines = jdLower
    .split(/[\n.•;]/)
    .filter((l) => /must|required|requirement|minimum|you have|qualif/.test(l))
    .join(" ");
  const cv = ` ${profileHay(profile)} `;

  const rank = (list) =>
    list
      .map((term) => {
        const n = countTerm(term, jdLower);
        if (!n) return null;
        const required = countTerm(term, ` ${reqLines} `) > 0;
        return {
          term,
          weight: n + (required ? 2 : 0),
          required,
          have: countTerm(term, cv) > 0,
        };
      })
      .filter(Boolean)
      .sort((a, b) => b.weight - a.weight);

  const hard = rank(HARD_SKILLS);
  const soft = rank(SOFT_SKILLS);

  const titleWords = (title || "")
    .toLowerCase()
    .replace(/\(.*?\)/g, "")
    .split(/[^a-z0-9+#]+/)
    .filter(
      (w) =>
        w.length > 2 &&
        ![
          "senior",
          "junior",
          "lead",
          "principal",
          "staff",
          "the",
          "and",
          "for",
          "with",
        ].includes(w)
    );
  const titleMatch =
    titleWords.length > 0 &&
    titleWords.filter((w) => cv.includes(w)).length / titleWords.length >= 0.6;

  const cover = (arr) => {
    const total = arr.reduce((s, k) => s + k.weight, 0);
    return total
      ? arr.filter((k) => k.have).reduce((s, k) => s + k.weight, 0) / total
      : null;
  };
  const hardCov = cover(hard);
  const softCov = cover(soft);
  // Jobscan-style blend: hard skills dominate, title and soft skills nudge.
  let score = null;
  if (hardCov !== null) {
    score =
      hardCov * 75 +
      (softCov === null ? 0.6 : softCov) * 10 +
      (title ? (titleMatch ? 15 : 0) : 9);
    score = Math.round(Math.max(0, Math.min(100, score)));
  }

  const split = (arr) => ({
    found: arr.filter((k) => k.have),
    missing: arr.filter((k) => !k.have),
  });
  return {
    score,
    hard: split(hard),
    soft: split(soft),
    titleMatch,
    hasTitle: !!title,
  };
}

// ===== DEEP EVALUATION (AI) =====
// Modeled on career-ops' A–H report: a judgement score on a 1–5 scale with a
// 4.0 apply line, posting legitimacy kept separate from the score, level
// strategy, the top CV changes, and STAR stories built ONLY from real
// experience. Never invents numbers the candidate doesn't have.
export const EVAL_BANDS = [
  { min: 4.5, label: "Strong match — apply now", tone: "good" },
  { min: 4.0, label: "Good match — worth applying", tone: "good" },
  {
    min: 3.5,
    label: "Decent — apply only with a specific reason",
    tone: "warn",
  },
  { min: 0, label: "Weak fit — probably skip", tone: "bad" },
];
export const bandFor = (score) =>
  EVAL_BANDS.find((b) => (Number(score) || 0) >= b.min) || EVAL_BANDS[3];

export async function evaluateJob(profile, job) {
  const cv = (profile.cvText || "").slice(0, 7000);
  const prompt = `You are a blunt, senior career coach. Evaluate whether this candidate should apply to this job. Your job is to help them choose well, not to flatter them.

CANDIDATE PROFILE:
${JSON.stringify(
  {
    headline: profile.headline,
    seniority: profile.seniority,
    yearsExperience: profile.yearsExperience,
    coreSkills: profile.coreSkills,
    tools: profile.tools,
    domains: profile.domains,
    targetTitles: profile.preferredTitles,
    keyProjects: profile.keyProjects,
  },
  null,
  1
)}
${cv ? `\nCV TEXT (cite from this):\n${cv}\n` : ""}
JOB:
Title: ${job.title || "(not given)"}
Company: ${job.company || "(not given)"}
Location: ${job.location || "(not given)"}
Description:
${(job.jd || "").slice(0, 6000)}

RULES:
- Score each dimension 1.0-5.0. "overall" is your judgement (not an average). 4.0+ means "apply".
- "evidence" must quote or closely paraphrase real lines from the CV/profile. Never invent experience, employers or numbers.
- Comp: only estimate if the JD states pay or the role/location makes a range well-known; otherwise say "insufficient data".
- Legitimacy is separate from the score: flag vague JDs, no company name, unrealistic pay, requests for payment/personal data.
- STAR stories must be built from the candidate's actual projects; if there isn't enough material, return fewer.
- Plain text inside strings. Keep every string under 220 characters.

Return ONLY valid JSON:
{
  "overall": 0.0,
  "verdict": "one sentence",
  "dimensions": [
    {"name": "Skills & experience match", "score": 0.0, "note": "string"},
    {"name": "Career direction fit", "score": 0.0, "note": "string"},
    {"name": "Seniority fit", "score": 0.0, "note": "string"},
    {"name": "Compensation", "score": 0.0, "note": "string"},
    {"name": "Culture & stability signals", "score": 0.0, "note": "string"}
  ],
  "evidence": [{"requirement": "from the JD", "proof": "from the CV", "strength": "strong|partial|missing"}],
  "redFlags": ["string"],
  "legitimacy": {"tier": "High confidence|Proceed with caution|Suspicious", "reason": "string"},
  "levelStrategy": "how to position seniority honestly for this role",
  "cvChanges": ["top 5 concrete edits to the CV for this role"],
  "starStories": [{"theme": "the JD need it answers", "situation": "string", "action": "string", "result": "string"}],
  "interviewQuestions": ["5 likely questions"]
}`;
  const parsed = await callAIJson(prompt, 6144);
  if (!parsed || typeof parsed.overall === "undefined")
    throw new Error("Could not evaluate this job — try again.");
  parsed.overall = Math.max(1, Math.min(5, Number(parsed.overall) || 1));
  parsed.evaluatedAt = Date.now();
  return parsed;
}

// ===== CSV EXPORT (your data, your spreadsheet) =====
export function applicationsToCsv(apps) {
  const cols = [
    ["title", "Title"],
    ["company", "Company"],
    ["location", "Location"],
    ["status", "Status"],
    ["matchScore", "Match"],
    ["evalScore", "Evaluation (1-5)"],
    ["dateAdded", "Added"],
    ["dateApplied", "Applied"],
    ["contactEmail", "Contact"],
    ["url", "Link"],
    ["notes", "Notes"],
  ];
  const cell = (v) => {
    const s = v === null || v === undefined ? "" : String(v);
    return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
  };
  const rows = apps.map((a) =>
    cols
      .map(([k]) => {
        if (k === "evalScore") return cell(a.evaluation?.overall?.toFixed?.(1));
        if (k.startsWith("date") && a[k])
          return cell(String(a[k]).slice(0, 10));
        return cell(a[k]);
      })
      .join(",")
  );
  return [cols.map((c) => c[1]).join(","), ...rows].join("\n");
}
