// JobHuntEvaluate.js
// The "should I apply?" layer of the Job Copilot.
//  1. Keyword scan: instant and local, Jobscan-style ATS coverage of the JD.
//  2. Deep evaluation: AI judgement on a 1–5 scale with a 4.0 apply line,
//     modeled on career-ops' A–H report (dimensions, cited evidence, posting
//     legitimacy kept separate, level strategy, CV edits, STAR stories).

import React, { useMemo, useState } from "react";
import {
  scanKeywords,
  evaluateJob,
  bandFor,
  getLastAIProvider,
} from "./jobHuntData";

function Meter({ value, max = 100, tone }) {
  const pct = Math.max(0, Math.min(100, (value / max) * 100));
  return (
    <div className={`jh-meter ${tone || ""}`}>
      <span style={{ width: `${pct}%` }} />
    </div>
  );
}

const toneForPct = (n) => (n >= 75 ? "good" : n >= 55 ? "warn" : "bad");

export function KeywordReport({ scan, compact = false }) {
  if (!scan || scan.score === null) {
    return (
      <p className="jh-muted">
        Paste a job description with a few concrete requirements to see keyword
        coverage.
      </p>
    );
  }
  const { hard, soft } = scan;
  const totalHard = hard.found.length + hard.missing.length;
  return (
    <div className="jh-kw">
      <div className="jh-kw-head">
        <div className={`jh-kw-score ${toneForPct(scan.score)}`}>
          {scan.score}
          <small>%</small>
        </div>
        <div className="jh-kw-summary">
          <strong>ATS keyword match</strong>
          <span>
            {hard.found.length} of {totalHard} hard skills found
            {scan.hasTitle &&
              (scan.titleMatch
                ? " · job title appears in your CV"
                : " · job title not in your CV")}
          </span>
          <Meter value={scan.score} tone={toneForPct(scan.score)} />
        </div>
      </div>
      {hard.missing.length > 0 && (
        <div className="jh-kw-group">
          <span className="jh-kw-label">Missing</span>
          <div className="jh-chips">
            {hard.missing.slice(0, compact ? 8 : 16).map((k) => (
              <span
                key={k.term}
                className={`jh-kw-chip miss ${k.required ? "req" : ""}`}
                title={
                  k.required
                    ? "Appears in a requirements line"
                    : "Mentioned in the JD"
                }
              >
                {k.term}
                {k.required && <em>required</em>}
              </span>
            ))}
          </div>
        </div>
      )}
      {hard.found.length > 0 && (
        <div className="jh-kw-group">
          <span className="jh-kw-label">Found</span>
          <div className="jh-chips">
            {hard.found.slice(0, compact ? 8 : 20).map((k) => (
              <span key={k.term} className="jh-kw-chip hit">
                {k.term}
              </span>
            ))}
          </div>
        </div>
      )}
      {!compact && soft.found.length + soft.missing.length > 0 && (
        <div className="jh-kw-group">
          <span className="jh-kw-label">Soft skills</span>
          <div className="jh-chips">
            {soft.found.map((k) => (
              <span key={k.term} className="jh-kw-chip hit">
                {k.term}
              </span>
            ))}
            {soft.missing.map((k) => (
              <span key={k.term} className="jh-kw-chip miss">
                {k.term}
              </span>
            ))}
          </div>
        </div>
      )}
      {!compact && hard.missing.length > 0 && (
        <p className="jh-muted jh-kw-tip">
          Only add a missing keyword if it's true. Work it into a bullet that
          shows where you used it, not into a skills dump.
        </p>
      )}
    </div>
  );
}

export function EvaluationReport({ ev, provider }) {
  if (!ev) return null;
  const band = bandFor(ev.overall);
  const legitTone =
    ev.legitimacy?.tier === "Suspicious"
      ? "bad"
      : ev.legitimacy?.tier === "Proceed with caution"
      ? "warn"
      : "good";
  return (
    <div className="jh-eval">
      <div className="jh-eval-head">
        <div className={`jh-eval-score ${band.tone}`}>
          {Number(ev.overall).toFixed(1)}
          <small>/5</small>
        </div>
        <div>
          <strong className={`jh-eval-band ${band.tone}`}>{band.label}</strong>
          <p>{ev.verdict}</p>
          {provider && (
            <em className="jh-provider">evaluated via {provider}</em>
          )}
        </div>
      </div>

      {ev.dimensions?.length > 0 && (
        <div className="jh-eval-dims">
          {ev.dimensions.map((d) => (
            <div className="jh-eval-dim" key={d.name}>
              <div className="jh-eval-dim-top">
                <span>{d.name}</span>
                <b>{Number(d.score).toFixed(1)}</b>
              </div>
              <Meter
                value={Number(d.score) || 0}
                max={5}
                tone={bandFor(d.score).tone}
              />
              {d.note && <p>{d.note}</p>}
            </div>
          ))}
        </div>
      )}

      {ev.legitimacy?.tier && (
        <div className={`jh-eval-legit ${legitTone}`}>
          <strong>Posting check: {ev.legitimacy.tier}</strong>
          <span>{ev.legitimacy.reason}</span>
        </div>
      )}

      {ev.evidence?.length > 0 && (
        <section className="jh-eval-sec">
          <h4>Requirements vs. your evidence</h4>
          <ul className="jh-eval-evidence">
            {ev.evidence.map((e, i) => (
              <li key={i} className={e.strength}>
                <span className="req">{e.requirement}</span>
                <span className="proof">{e.proof}</span>
              </li>
            ))}
          </ul>
        </section>
      )}

      {ev.redFlags?.length > 0 && (
        <section className="jh-eval-sec">
          <h4>Red flags</h4>
          <ul className="jh-eval-list">
            {ev.redFlags.map((r, i) => (
              <li key={i}>{r}</li>
            ))}
          </ul>
        </section>
      )}

      {ev.levelStrategy && (
        <section className="jh-eval-sec">
          <h4>How to pitch your level</h4>
          <p>{ev.levelStrategy}</p>
        </section>
      )}

      {ev.cvChanges?.length > 0 && (
        <section className="jh-eval-sec">
          <h4>CV changes for this role</h4>
          <ol className="jh-eval-list">
            {ev.cvChanges.map((c, i) => (
              <li key={i}>{c}</li>
            ))}
          </ol>
        </section>
      )}

      {ev.starStories?.length > 0 && (
        <section className="jh-eval-sec">
          <h4>Interview stories (STAR)</h4>
          <div className="jh-eval-stars">
            {ev.starStories.map((s, i) => (
              <details key={i}>
                <summary>{s.theme}</summary>
                <p>
                  <b>Situation</b> {s.situation}
                </p>
                <p>
                  <b>Action</b> {s.action}
                </p>
                <p>
                  <b>Result</b> {s.result}
                </p>
              </details>
            ))}
          </div>
        </section>
      )}

      {ev.interviewQuestions?.length > 0 && (
        <section className="jh-eval-sec">
          <h4>Likely interview questions</h4>
          <ul className="jh-eval-list">
            {ev.interviewQuestions.map((q, i) => (
              <li key={i}>{q}</li>
            ))}
          </ul>
        </section>
      )}
    </div>
  );
}

// Standalone evaluator: paste any JD (or start from a job) → scan + evaluate.
// `job` seeds the fields; `onSave(job)` stores the result in the pipeline.
export function EvalPanel({
  profile,
  job,
  onSave,
  saveLabel = "Save to pipeline",
}) {
  const [title, setTitle] = useState(job?.title || "");
  const [company, setCompany] = useState(job?.company || "");
  const [jd, setJd] = useState(job?.jd || "");
  const [ev, setEv] = useState(job?.evaluation || null);
  const [provider, setProvider] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [saved, setSaved] = useState(false);

  const scan = useMemo(
    () => (jd.trim().length > 40 ? scanKeywords(profile, jd, title) : null),
    [profile, jd, title]
  );
  const hasProfile = !!(profile?.coreSkills?.length || profile?.cvText);
  const shortJd = jd.trim().length > 0 && jd.trim().length < 700;

  const run = async () => {
    if (busy) return;
    setBusy(true);
    setError("");
    setSaved(false);
    try {
      const result = await evaluateJob(profile, {
        ...(job || {}),
        title,
        company,
        jd,
      });
      setEv(result);
      setProvider(getLastAIProvider());
    } catch (e) {
      setError(e.message || "Evaluation failed — try again.");
    } finally {
      setBusy(false);
    }
  };

  const save = () => {
    onSave?.({
      ...(job || {}),
      title: title.trim() || "Untitled role",
      company: company.trim() || "Unknown company",
      jd: jd.slice(0, 8000),
      evaluation: ev || job?.evaluation || null,
      matchScore: scan?.score ?? job?.matchScore ?? 0,
    });
    setSaved(true);
  };

  return (
    <div className="jh-evalpanel">
      <div className="jh-ev-grid">
        <div className="jh-ev-left">
          <div className="jh-evalpanel-fields">
            <label className="jh-field">
              <span>Job title</span>
              <input
                value={title}
                onChange={(e) => setTitle(e.target.value)}
                placeholder="e.g. Machine Learning Engineer"
              />
            </label>
            <label className="jh-field">
              <span>Company</span>
              <input
                value={company}
                onChange={(e) => setCompany(e.target.value)}
                placeholder="e.g. Razorpay"
              />
            </label>
          </div>
          <label className="jh-field">
            <span>Job description</span>
            <textarea
              rows={7}
              value={jd}
              onChange={(e) => setJd(e.target.value)}
              placeholder="Paste the full job description. The keyword scan updates as you type."
            />
          </label>
          {shortJd && (
            <p className="jh-muted">
              This looks like a snippet. Job boards often truncate descriptions,
              so paste the full JD from the posting for an accurate result.
            </p>
          )}
          {!hasProfile && (
            <p className="jh-muted">
              Add your CV at the top first. Without it there's nothing to match
              against.
            </p>
          )}
        </div>
        <aside className="jh-ev-right" aria-live="polite">
          {scan ? (
            <KeywordReport scan={scan} />
          ) : (
            <div className="jh-ev-placeholder">
              <strong>Keyword check</strong>
              <span>
                Paste a description and this fills in as you type: match %,
                required keywords you're missing, and the ones you already
                cover.
              </span>
            </div>
          )}
        </aside>
      </div>

      <div className="jh-evalpanel-actions">
        <button
          className="jh-btn primary"
          onClick={run}
          disabled={busy || !hasProfile || jd.trim().length < 80}
          title="AI evaluation: fit score, evidence, red flags, CV edits and interview prep"
        >
          {busy ? "Evaluating…" : ev ? "Re-evaluate" : "Get the AI verdict"}
        </button>
        {onSave && (
          <button
            className="jh-btn ghost"
            onClick={save}
            disabled={!jd.trim() || saved}
          >
            {saved ? "Saved ✓" : saveLabel}
          </button>
        )}
      </div>
      {busy && (
        <div className="jh-draft-loading">
          Reading the JD against your CV. This takes about 10–20 seconds.
        </div>
      )}
      {error && <div className="jh-error">{error}</div>}
      <EvaluationReport ev={ev} provider={provider} />
    </div>
  );
}
