// JobHuntHero.js
// The /jobhunt hero: the site's headline language (Google Sans Bold, three
// tones, Montserrat eyebrow, hairline facts) plus one signature visual drawn
// from the product's real data. Two visuals for comparison behind a
// dev-only switcher (?hero=radar | form); the unpicked one gets deleted.

import React, { useEffect, useMemo, useState } from "react";
import { COMPANY_BOARDS } from "./jobBoards";

// ---------- deterministic jitter so the layout doesn't jump on re-render
const hash = (s) => {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++)
    h = Math.imul(h ^ s.charCodeAt(i), 16777619);
  return ((h >>> 0) % 1000) / 1000;
};

// ===== Visual A: match radar =====
function Radar({ jobs, initials }) {
  const R = 230;
  const nodes = useMemo(() => {
    const src = jobs.length
      ? jobs.slice(0, 10).map((j) => ({
          id: j.id,
          name: j.company,
          sub: j.title,
          score: j.matchScore,
        }))
      : COMPANY_BOARDS.slice(0, 10).map((b, i) => ({
          id: b.slug,
          name: b.name,
          sub: b.tag,
          score: 58 + Math.round(hash(b.slug) * 34),
          idle: true,
        }));
    return src.map((n, i) => {
      const angle = (i / src.length) * 360 + hash(n.id) * 22 - 11;
      const dist =
        62 + ((100 - Math.max(40, Math.min(98, n.score))) / 60) * (R - 70);
      const rad = ((angle - 90) * Math.PI) / 180;
      return { ...n, angle, x: Math.cos(rad) * dist, y: Math.sin(rad) * dist };
    });
  }, [jobs]);

  return (
    <div className="jhh-radar" aria-hidden="true">
      <svg viewBox="-260 -260 520 520">
        <defs>
          <radialGradient id="jhhCore" cx="50%" cy="50%" r="50%">
            <stop offset="0%" stopColor="var(--jhh-a)" stopOpacity="0.35" />
            <stop offset="100%" stopColor="var(--jhh-a)" stopOpacity="0" />
          </radialGradient>
        </defs>
        <circle r={R + 10} fill="url(#jhhCore)" opacity="0.35" />
        {[0.28, 0.52, 0.76, 1].map((k) => (
          <circle key={k} r={R * k} className="ring" />
        ))}
        <line x1={-R} y1="0" x2={R} y2="0" className="axis" />
        <line x1="0" y1={-R} x2="0" y2={R} className="axis" />
        <text x="6" y={-R * 0.28 + 14} className="ring-label">
          90%
        </text>
        <text x="6" y={-R * 0.76 + 14} className="ring-label">
          60%
        </text>
      </svg>
      <div className="jhh-sweep" />
      <div className="jhh-core">
        <b>{initials}</b>
        <span>Your CV</span>
      </div>
      {nodes.map((n) => (
        <div
          key={n.id}
          className={`jhh-node ${
            n.score >= 75 ? "good" : n.score >= 60 ? "warn" : "dim"
          } ${n.idle ? "idle" : ""}`}
          style={{
            left: `calc(50% + ${(n.x / 520) * 100}%)`,
            top: `calc(50% + ${(n.y / 520) * 100}%)`,
            animationDelay: `${(n.angle / 360) * 6}s`,
          }}
        >
          <i />
          <span>
            <b>{n.name}</b>
            {!n.idle && <em>{n.score}%</em>}
          </span>
        </div>
      ))}
    </div>
  );
}

// ===== Visual B: an application filling itself in =====
function FormInFlight({ jobs, profile }) {
  const examples = useMemo(() => {
    const pick = jobs.length
      ? jobs.slice(0, 3)
      : [
          { company: "Databricks", title: "AI Engineer" },
          { company: "Anthropic", title: "Applied AI Engineer" },
        ];
    const proof = (
      profile?.keyProjects?.[0] ||
      "shipped a RAG platform that serves 80,000+ documents a month"
    ).replace(/^[^:]*:\s*/, "");
    return pick.map((j) => ({
      company: j.company,
      title: j.title,
      fields: [
        ["Full name", profile?.fullName || "Alex Morgan"],
        ["Email", "you@gmail.com"],
        ["LinkedIn", "linkedin.com/in/you"],
      ],
      why: `What draws me to ${
        j.company
      } is the chance to work on ${j.title.toLowerCase()} problems at real scale. Most recently I ${proof
        .charAt(0)
        .toLowerCase()}${proof.slice(1)}.`,
    }));
  }, [jobs, profile]);

  const [idx, setIdx] = useState(0);
  const [typed, setTyped] = useState(0);
  const ex = examples[idx % examples.length];
  const total = ex.why.length;

  useEffect(() => {
    const reduce = window.matchMedia?.("(prefers-reduced-motion: reduce)")
      .matches;
    if (reduce) {
      setTyped(total);
      return undefined;
    }
    if (typed < total) {
      const t = setTimeout(() => setTyped((n) => Math.min(total, n + 2)), 28);
      return () => clearTimeout(t);
    }
    const t = setTimeout(() => {
      setTyped(0);
      setIdx((i) => i + 1);
    }, 3200);
    return () => clearTimeout(t);
  }, [typed, total]);

  const done = typed >= total;
  return (
    <div className="jhh-form" aria-hidden="true">
      <div className="jhh-form-glow" />
      <div className="jhh-form-card">
        <div className="jhh-form-top">
          <span className="jhh-dot" />
          <span>
            Application · <b>{ex.company}</b>
          </span>
          <em>{ex.title}</em>
        </div>
        {ex.fields.map(([k, v], i) => (
          <div
            className="jhh-field filled"
            key={k}
            style={{ animationDelay: `${i * 0.12}s` }}
          >
            <label>{k}</label>
            <div>{v}</div>
          </div>
        ))}
        <div className="jhh-field">
          <label>Why {ex.company}?</label>
          <div className="jhh-type">
            {ex.why.slice(0, typed)}
            {!done && <i className="jhh-caret" />}
          </div>
        </div>
        <div className="jhh-row">
          <span className="jhh-file">
            <b>resume.pdf</b> tailored · 5 lines rewritten
          </span>
          <span className="jhh-needs">1 needs you</span>
        </div>
        <div className="jhh-form-foot">
          <span>
            {done ? "Ready. You review and submit." : "Drafting from your CV…"}
          </span>
          <button tabIndex={-1} className={done ? "on" : ""}>
            Submit
          </button>
        </div>
      </div>
      <div className="jhh-form-under">
        <span />
        <span />
      </div>
    </div>
  );
}

// ===== Auto-rotating hero: radar (the agent watching) and form (you
// applying). A quiet pager shows which is on; clicking one jumps to it and
// the rotation carries on from there.
function ViewPager({ mode, onPick }) {
  return (
    <div className="jhh-pager" role="tablist" aria-label="Hero view">
      {[
        ["radar", "Agent radar"],
        ["form", "Application"],
      ].map(([id, label]) => (
        <button
          key={id}
          role="tab"
          aria-selected={mode === id}
          className={mode === id ? "on" : ""}
          onClick={() => onPick(id)}
        >
          <i />
          {label}
        </button>
      ))}
    </div>
  );
}

const VIEW_KEY = "jobhunt.heroView";

export default function JobHuntHero({
  owner,
  modeLabel,
  profile,
  shortlist,
  apps,
  onFind,
  onEvaluate,
}) {
  const [variant, setVariant] = useState(() => {
    const q = new URLSearchParams(window.location.search).get("hero");
    if (q === "radar" || q === "form") return q;
    try {
      return localStorage.getItem(VIEW_KEY) || "radar";
    } catch (e) {
      return "radar";
    }
  });
  const pick = (id) => {
    setVariant(id);
    try {
      localStorage.setItem(VIEW_KEY, id);
    } catch (e) {
      /* ignore */
    }
  };

  // Rotate continuously so both views get seen (paused for reduced motion).
  useEffect(() => {
    if (window.matchMedia?.("(prefers-reduced-motion: reduce)").matches)
      return undefined;
    const t = setTimeout(
      () => setVariant((v) => (v === "radar" ? "form" : "radar")),
      variant === "radar" ? 9000 : 13000
    );
    return () => clearTimeout(t);
  }, [variant]);

  const initials =
    (profile?.fullName || "You")
      .split(/\s+/)
      .map((w) => w[0])
      .slice(0, 2)
      .join("")
      .toUpperCase() || "YOU";
  const applied = apps.filter((a) =>
    ["applied", "callback", "interviewing", "offer"].includes(a.status)
  ).length;

  return (
    <header className="jhh">
      <div className="jhh-copy">
        <p className="jhh-eyebrow">
          <i />
          Job Copilot
          <span className={`jhh-mode ${owner ? "owner" : ""}`}>
            {modeLabel}
          </span>
        </p>
        <h1 className="jhh-title">
          <span>Fewer applications.</span>
          <span>
            More <em>interviews.</em>
          </span>
          <span className="dim">You press send.</span>
        </h1>
        <p className="jhh-lede">
          Upload your CV once. An agent watches company career pages, ranks
          every opening against you and prepares each application: tailored
          resume lines, answers to the real form. You read it and press Submit.
        </p>
        <div className="jhh-actions">
          <button className="jhh-cta" onClick={onFind}>
            See jobs picked for you
          </button>
          <button className="jhh-ghost" onClick={onEvaluate}>
            Check a job description →
          </button>
        </div>
        <div className="jhh-facts">
          <p>
            <b>{COMPANY_BOARDS.length}</b>
            <span>career pages watched</span>
          </p>
          <p>
            <b>{shortlist.length || "—"}</b>
            <span>picked for you</span>
          </p>
          <p>
            <b>{applied}</b>
            <span>applications sent</span>
          </p>
          <p>
            <b>0</b>
            <span>sign-ups needed</span>
          </p>
        </div>
      </div>

      <div className={`jhh-visual mood-${variant}`}>
        <div className="jhh-stage" key={variant}>
          {variant === "radar" ? (
            <Radar jobs={shortlist} initials={initials} />
          ) : (
            <FormInFlight jobs={shortlist} profile={profile} />
          )}
        </div>
        <ViewPager mode={variant} onPick={pick} />
      </div>
    </header>
  );
}
